// Per-user installation and rollback. Never run a command supplied by a controller.
import { execFile } from 'node:child_process'
import { createHash, randomUUID, verify } from 'node:crypto'
import { constants } from 'node:fs'
import {
  chmod,
  copyFile,
  link,
  lstat,
  mkdir,
  mkdtemp,
  readFile,
  readdir,
  readlink,
  rename,
  rm,
  symlink,
  unlink,
  writeFile,
} from 'node:fs/promises'
import { basename, dirname, join, resolve } from 'node:path'
import { promisify } from 'node:util'
import { setTimeout as sleep } from 'node:timers/promises'
import { serviceDefinition } from '../../computer-host/service-install.js'
import { localRequest } from '../../computer-host/local.js'
import {
  bundledHostManifests,
  bundledHostVersion,
  bundledPublisherKeyPath,
  prepareBundledHost,
} from '../../computer-host/bundled-artifacts.js'
import { bundledEncoder, prepareBundledEncoder } from '../../computer-host/bundled-encoder.js'

const exec = promisify(execFile)
const parts = { host: 'current', desktop: 'desktop-current' }
const hash = (bytes) => createHash('sha256').update(bytes).digest('hex')
export const shipped = {
  version: bundledHostVersion,
  manifests: bundledHostManifests,
  key: bundledPublisherKeyPath,
  prepare: prepareBundledHost,
  encoder: bundledEncoder,
  copyEncoder: prepareBundledEncoder,
}
export async function maybe(operation) {
  try {
    return await operation
  } catch (e) {
    if (e.code !== 'ENOENT') throw e
  }
}
export async function atomic(path, data, mode = 0o600) {
  const temp = path + '.' + randomUUID()
  await mkdir(dirname(path), { recursive: true, mode: 0o700 })
  try {
    await writeFile(temp, data, { flag: 'wx', mode })
    await rename(temp, path)
  } finally {
    await rm(temp, { force: true })
  }
}
export function compareVersions(a, b) {
  for (let i = 0; i < 3; i++) {
    const difference = Number(a.split('.')[i]) - Number(b.split('.')[i])
    if (difference) return Math.sign(difference)
  }
  return 0
}
const xml = (s) =>
  s.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;')
const unxml = (s) =>
  s.replaceAll('&quot;', '"').replaceAll('&lt;', '<').replaceAll('&gt;', '>').replaceAll('&amp;', '&')
const marker = 'Generated by Godbot Computer Host'
function argumentsOf(text) {
  const body = text.match(/<key>ProgramArguments<\/key>\s*<array>([\s\S]*?)<\/array>/)?.[1]
  return [...(body || '').matchAll(/<string>([^<]*)<\/string>/g)].map((m) => unxml(m[1]))
}
const flag = (args, key) => (args.includes(key) ? args[args.indexOf(key) + 1] : undefined)
export class HostInstallation {
  constructor({ home, hostHome, management, bundle = shipped, run = exec, request = localRequest }) {
    Object.assign(this, { home, hostHome, management, bundle, run, request })
    this.store = join(home, '.local/share/godbot-computer')
    this.launcher = join(home, '.local/bin/godbot-computer')
    this.env = {
      HOME: home,
      PATH: process.env.PATH || '/usr/bin:/bin',
      ...(process.env.TMPDIR && { TMPDIR: process.env.TMPDIR }),
    }
    this.domain = 'gui/' + process.getuid()
  }
  async existingHome() {
    const dir = join(this.home, 'Library/LaunchAgents')
    const candidates = []
    for (const file of (await maybe(readdir(dir))) || []) {
      if (!/^io\.github\.godbot\.computer\.[0-9a-f]{12}\.plist$/.test(file)) continue
      const path = join(dir, file)
      if (!(await lstat(path)).isFile()) continue
      const text = await readFile(path, 'utf8')
      const args = argumentsOf(text)
      const home = flag(args, '--home')
      if (!text.includes(marker) || args[0] !== this.launcher || !home || resolve(home) !== home) continue
      if (basename(serviceDefinition('darwin', { home }, this.home).path) === file) candidates.push(home)
    }
    if (candidates.includes(this.hostHome)) return this.hostHome
    if (candidates.length > 1)
      throw Error(
        'Several standalone Computer Host services exist. Select the intended host with GODBOT_COMPUTER_HOME.',
      )
    return candidates[0] || this.hostHome
  }
  definition(directory, relay, encoder) {
    return serviceDefinition(
      'darwin',
      { home: directory, relay, encoder, launcher: this.launcher },
      this.home,
    )
  }
  async plist(directory) {
    const path = this.definition(directory).path
    const info = await maybe(lstat(path))
    if (!info) return
    if (!info.isFile() || info.uid !== process.getuid() || info.mode & 0o022)
      throw Error('Unrecognized Computer Host login service')
    const text = await readFile(path, 'utf8')
    const args = argumentsOf(text)
    if (!text.includes(marker) || args[0] !== this.launcher || flag(args, '--home') !== directory)
      throw Error('Unrecognized Computer Host login service')
    return text
  }
  configuredPlist(directory, relay, encoder, old) {
    if (!old) return this.definition(directory, relay, encoder).text
    let text = old
    const vars = /<key>EnvironmentVariables<\/key>\s*<dict>([\s\S]*?)<\/dict>/
    if (!vars.test(text)) throw Error('The standalone login service has no recognized environment')
    const newVar = (key, value, body) => {
      const rx = new RegExp('<key>' + key + '</key>\\s*<string>[^<]*</string>')
      const addition = '<key>' + key + '</key><string>' + xml(value) + '</string>'
      return rx.test(body) ? body.replace(rx, () => addition) : body + addition
    }
    text = text.replace(
      vars,
      (_, body) =>
        '<key>EnvironmentVariables</key><dict>' +
        newVar('GODBOT_DESKTOP_FFMPEG', encoder, newVar('HOME', this.home, body)) +
        '</dict>',
    )
    const args = argumentsOf(text)
    if (flag(args, '--relay') === relay) return text
    if (args.includes('--relay'))
      return text.replace(
        /(<string>--relay<\/string>\s*)<string>[^<]*<\/string>/,
        (_, prefix) => prefix + '<string>' + xml(relay) + '</string>',
      )
    return text.replace(
      /(<key>ProgramArguments<\/key>\s*<array>[\s\S]*?)<\/array>/,
      (_, body) => body + '<string>--relay</string><string>' + xml(relay) + '</string></array>',
    )
  }
  cmd(file, args) {
    return this.run(file, args, { env: this.env, timeout: 60_000, maxBuffer: 2 * 1024 * 1024 })
  }
  async loaded(directory) {
    try {
      await this.cmd('/bin/launchctl', ['print', this.domain + '/' + this.definition(directory).label])
      return true
    } catch (e) {
      if (
        !/could not find service|service not found|no such process/i.test(String(e.stderr)) &&
        e.code !== 113
      )
        throw e
      return false
    }
  }
  async serviceRunning(directory) {
    const { stdout } = await this.cmd('/bin/launchctl', [
      'print',
      this.domain + '/' + this.definition(directory).label,
    ])
    return /^\s*pid = \d+\s*$/m.test(stdout)
  }
  async stop(directory) {
    if (await this.loaded(directory)) {
      await this.cmd('/bin/launchctl', ['bootout', this.domain + '/' + this.definition(directory).label])
      for (let i = 0; i < 50; i++) {
        if (!(await this.loaded(directory))) return
        await sleep(100)
      }
      throw Error('Computer Host took too long to stop')
    }
  }
  async start(directory) {
    if (!(await this.loaded(directory)))
      await this.cmd('/bin/launchctl', ['bootstrap', this.domain, this.definition(directory).path])
    else await this.cmd('/bin/launchctl', ['kickstart', this.domain + '/' + this.definition(directory).label])
  }
  async daemon(directory) {
    try {
      return await this.request(directory, 'status')
    } catch (e) {
      if (['ENOENT', 'ECONNREFUSED'].includes(e.code)) return
      throw e
    }
  }
  async configRelay(directory) {
    const file = join(directory, 'identity.json')
    const info = await maybe(lstat(file))
    if (!info) return
    if (!info.isFile() || info.uid !== process.getuid() || info.mode & 0o077)
      throw Error('The standalone host identity is not privately owned')
    return JSON.parse(await readFile(file, 'utf8')).relay
  }
  async ready(directory, relay, requireOnline) {
    for (let i = 0; i < 75; i++) {
      let s
      try {
        s = await this.daemon(directory)
      } catch (e) {
        if (!/starting|closed|shutting down/i.test(e.message)) throw e
      }
      if (s?.relay === relay && s.terminal && (!requireOnline || s.status === 'online')) return s
      await sleep(150)
    }
    throw Error('Computer Host did not start with the configured relay')
  }
  async installed() {
    const installed = {}
    const trusted = await maybe(readFile(join(this.store, 'publisher.pem')))
    const key = await readFile(this.bundle.key)
    if (trusted && !trusted.equals(key)) throw Error('The standalone Computer Host uses another publisher')
    for (const [component, link] of Object.entries(parts)) {
      const target = await maybe(readlink(join(this.store, link)))
      if (!target) continue
      if (!trusted || !/^releases\/[^/]+$/.test(target))
        throw Error('The installed Computer Host package is unrecognized')
      const dir = join(this.store, target)
      const bytes = await readFile(join(dir, 'manifest.json'))
      const m = JSON.parse(bytes)
      if (
        !verify('sha256', bytes, key, await readFile(join(dir, 'manifest.sig'))) ||
        m.component !== component ||
        m.platform !== 'darwin' ||
        m.arch !== 'arm64' ||
        !/^\d+\.\d+\.\d+$/.test(m.version)
      )
        throw Error('The installed Computer Host signature is invalid')
      const digest = hash(bytes)
      if (target !== 'releases/' + component + '-' + m.version + '-darwin-arm64-' + digest.slice(0, 12))
        throw Error('The installed Computer Host release path is invalid')
      installed[component] = { version: m.version, digest, dir, files: m.files }
    }
    return installed
  }
  async verifyInstalled(packages) {
    for (const record of Object.values(packages)) {
      for (const [name, digest] of Object.entries(record.files)) {
        if (!name || name.startsWith('/') || name.split('/').some((x) => !x || x === '..' || x === '.'))
          throw Error('Invalid installed Computer Host manifest path')
        const path = join(record.dir, name)
        const s = await lstat(path)
        if (
          !s.isFile() ||
          s.uid !== process.getuid() ||
          s.mode & 0o022 ||
          hash(await readFile(path)) !== digest
        )
          throw Error('Installed Computer Host contents do not match the signed package')
      }
    }
    if (packages.host && hash(await readFile(this.launcher)) !== packages.host.files['bin/godbot-computer'])
      throw Error('The Computer Host launcher does not match the signed package')
  }
  async encoderInfo() {
    const enc = await this.bundle.encoder()
    return this.encoderPath(enc?.sha256)
  }
  encoderPath(digest) {
    if (!/^[a-f0-9]{64}$/.test(digest)) throw Error('This Godbot package has no verified Mac video encoder')
    return { path: join(this.store, 'bundled-encoder', digest, 'ffmpeg'), digest }
  }
  async hasEncoder(enc) {
    const s = await maybe(lstat(enc.path))
    return Boolean(
      s?.isFile() &&
        s.uid === process.getuid() &&
        s.mode & 0o111 &&
        !(s.mode & 0o022) &&
        hash(await readFile(enc.path)) === enc.digest,
    )
  }
  async installEncoder(enc) {
    if (await this.hasEncoder(enc)) return
    await mkdir(dirname(enc.path), { recursive: true, mode: 0o700 })
    await this.bundle.copyEncoder(enc.path, enc.digest)
    if (!(await this.hasEncoder(enc))) throw Error('Installed video encoder verification failed')
  }
  async install(staged, component) {
    await this.cmd(join(staged[component + 'Dir'], 'install.sh'), ['--trust-key', staged.publisherKeyPath])
  }
  async openPermissions() {
    const app = join(this.store, parts.desktop, 'native/Godbot Computer Host.app')
    await this.cmd('/usr/bin/codesign', [
      '--verify',
      '--strict',
      '-R=identifier "io.github.renjiegod.godbot.computerhost" and anchor apple generic',
      app,
    ])
    await this.cmd('/usr/bin/open', ['-a', app])
  }
  backupPaths(directory) {
    return [
      this.definition(directory).path,
      join(directory, 'identity.json'),
      this.launcher,
      join(this.store, 'publisher.pem'),
      join(this.home, 'Applications/Godbot Computer Host.app'),
      ...Object.values(parts).flatMap((x) => [join(this.store, x), join(this.store, x + '-previous')]),
    ]
  }
  async snapshot(directory, loaded, desiredBefore, candidates) {
    const tmp = await mkdtemp(join(this.management, '.prepare-'))
    const files = []
    try {
      for (const [i, path] of this.backupPaths(directory).entries()) {
        const s = await maybe(lstat(path))
        if (!s) {
          files.push(null)
          continue
        }
        if (s.isSymbolicLink()) {
          files.push({ target: await readlink(path) })
          continue
        }
        // Other apps at ~/Applications/Godbot Computer Host.app are left alone by the installer.
        if (i === 4 && s.isDirectory()) {
          files.push({ untouched: true })
          continue
        }
        if (!s.isFile() || s.uid !== process.getuid() || s.mode & 0o022)
          throw Error('Unsafe file in standalone Computer Host installation')
        const backup = join(tmp, String(i))
        if (i === 1) {
          try {
            await link(path, backup)
          } catch (e) {
            if (e.code !== 'EXDEV') throw e
            await copyFile(path, backup, constants.COPYFILE_EXCL)
          }
        } else await copyFile(path, backup, constants.COPYFILE_EXCL)
        files.push({ mode: s.mode & 0o777 })
      }
      await atomic(
        join(tmp, 'journal.json'),
        JSON.stringify({ directory, loaded, desiredBefore, candidates, files }),
      )
      await rename(tmp, join(this.management, 'transaction'))
    } finally {
      await rm(tmp, { recursive: true, force: true })
    }
  }
  async rollback() {
    const dir = join(this.management, 'transaction')
    const raw = await maybe(readFile(join(dir, 'journal.json'), 'utf8'))
    if (!raw) return
    const j = JSON.parse(raw)
    const paths = this.backupPaths(j.directory)
    // A standalone installer does not take the dsh profiles' lock. Never undo a
    // signed release installed independently while this transaction was interrupted.
    for (const [component, link] of Object.entries(parts)) {
      const path = join(this.store, link)
      const active = await maybe(readlink(path))
      if (active !== j.files[paths.indexOf(path)]?.target && active !== j.candidates?.[component]) {
        await this.installed()
        if (j.loaded && !(await this.loaded(j.directory)) && (await this.plist(j.directory))) {
          await this.start(j.directory)
        }
        return j.desiredBefore
      }
    }
    const instance = await this.daemon(j.directory)
    if (instance && (await this.request(j.directory, 'sessions')).length)
      throw Error('Waiting for active sessions before restoring the Computer Host')
    await this.stop(j.directory)
    for (const [i, path] of paths.entries()) {
      const old = j.files[i]
      if (old?.untouched) continue
      if (!old) {
        await maybe(unlink(path))
        continue
      }
      await mkdir(dirname(path), { recursive: true, mode: 0o700 })
      const tmp = path + '.' + randomUUID()
      try {
        if (old.target !== undefined) await symlink(old.target, tmp)
        else if (i === 1) {
          try {
            await link(join(dir, String(i)), tmp)
          } catch (e) {
            if (e.code !== 'EXDEV') throw e
            await copyFile(join(dir, String(i)), tmp)
            await chmod(tmp, old.mode)
          }
        } else {
          await copyFile(join(dir, String(i)), tmp)
          await chmod(tmp, old.mode)
        }
        await rename(tmp, path)
      } finally {
        await rm(tmp, { force: true })
      }
    }
    if (j.loaded) await this.start(j.directory)
    return j.desiredBefore
  }
}
